import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import "./style/Comparison.css";

const BASE_URL = "https://salam29.pythonanywhere.com";
const ENDPOINTS = {
  "الخوارزمية الجينية (GA)": "/api/ga",
  "GA + Mutual Information": "/api/ga_mi",
  "GA + PCA": "/api/ga_pca",
  "GA + RFE": "/api/ga_rfe",
  "GA + Chi-Square": "/api/ga_chi",
};

function Comparison() {
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchData = async () => {
      try {
        const allResults = [];

        for (const [name, endpoint] of Object.entries(ENDPOINTS)) {
          const res = await fetch(`${BASE_URL}${endpoint}`, { method: "GET" });
          const data = await res.json();

          // نحاول استخراج الحقول بشكل مرن حسب الرد القادم من الباك
          const accuracy =
            data.accuracy ??
            data.model_accuracy ??
            data.fitness ??
            data.best_fitness ??
            null;

          const numFeatures =
            data.num_selected ??
            data.num_selected_features ??
            data.selected_features_count ??
            null;

          allResults.push({
            method: name,
            accuracy: accuracy
              ? `${(accuracy * (accuracy <= 1 ? 100 : 1)).toFixed(2)}%`
              : "غير متاح",
            features: numFeatures ?? "غير متاح",
          });
        }

        setResults(allResults);
      } catch (err) {
        console.error("خطأ أثناء جلب البيانات:", err);
        setError("تعذّر تحميل نتائج المقارنة.");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  return (
    <div className="comparison-container">
      <h1 className="comparison-title">مقارنة بين طرق اختيار الخصائص</h1>

      <p className="comparison-description">
        يوضح الجدول التالي نتائج الطرق المختلفة لاختيار الخصائص من خادم
        PythonAnywhere. كل طريقة تُظهر عدد الخصائص المختارة ودقّة النموذج.
      </p>

      {loading ? (
        <p className="loading-text">⏳ جارٍ تحميل النتائج...</p>
      ) : error ? (
        <p className="error-text">{error}</p>
      ) : (
        <table className="comparison-table">
          <thead>
            <tr>
              <th>الطريقة</th>
              <th>عدد الخصائص المختارة</th>
              <th>دقة النموذج</th>
            </tr>
          </thead>
          <tbody>
            {results.map((row, index) => (
              <tr key={index}>
                <td style={{ fontWeight: "bold", color: "#be185d" }}>
                  {row.method}
                </td>
                <td>{row.features}</td>
                <td>{row.accuracy}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <button onClick={() => navigate("/results")} className="comparison-btn">
        العودة إلى النتائج
      </button>
    </div>
  );
}

export default Comparison;
